import { test, expect } from '@playwright/test';

test('qeydiyyat forması göndərilir', async ({ page }) => {
  await page.goto('/qeydiyyat');

  await page.getByLabel('Ad').fill('Aysel');
  await page.getByLabel('Email').fill('aysel@mail.az');
  await page.getByLabel('Şifrə', { exact: true }).fill('Test123!');
  await page.getByLabel('Şəhər').selectOption('Bakı');
  await page.getByLabel('Şərtlərlə razıyam').check();
