import { test, expect } from '@playwright/test';

test.describe('Səbət', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/mehsullar');
  });

  test('məhsul əlavə olunur', async ({ page }) => {
    await page.getByRole('button', { name: 'Səbətə at' }).first().click();
    await expect(page.getByTestId('sebet-sayi')).toHaveText('1');
  });

  test('boş səbətdə mesaj görünür', async ({ page }) => {
    await page.getByRole('link', { name: 'Səbət' }).click();
    await expect(page.getByText('Səbətiniz boşdur')).toBeVisible();
  });
});
